function processPayment(payment: Payment) {
  if (!payment || payment.amount <= 0) {
    throw new Error('invalid payment');
  }
  account.debit(payment.amount);
  gateway.charge(payment);
}

async function registerUser(data: any) {
  const user = await db.insert('users', data);
  if (!validateUser(user)) {
    throw new Error('invalid user');
  }
  return user;
}

// Version A: persistence then validation
async function createOrderA(order) {
  const saved = await db.save('orders', order);
  if (!isValid(saved)) {
    await audit.log('invalid order persisted');
    throw new Error('Invalid order');
  }
  return saved;
}

// Version B: validation then persistence
async function createOrderB(order) {
  if (!isValid(order)) {
    throw new Error('Invalid order');
  }
  return await db.save('orders', order);
}
